// Safe input handling for Section 01
let inputData;
try {
  inputData = $input.first().json;
  console.log('✅ Input data received:', Object.keys(inputData || {}));
} catch (error) {
  console.error('❌ Input data error:', error.message);
  inputData = {};
}

// Extract company information safely
const companyId = inputData?.company_id || 'unknown_company';
const companyName = inputData?.company_name || 'Unknown Company';
const companyFolderName = inputData?.company_folder_name || companyName;

console.log('🔄 SECTION 01: Introduction & Engagement Context');
console.log('═'.repeat(50));
console.log('🏢 Company:', companyName);
console.log('🆔 Company ID:', companyId);
console.log('📁 Folder:', companyFolderName);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyFolderName,
    section_number: 1,
    section_title: 'Introduction & Engagement Context',
    section_description: 'Engagement framing, scope of work, methodology, and Big 4 due diligence standards',
    processing_status: 'initialized',
    started_at: new Date().toISOString()
  }
};

// Combine initialization data with RAG results
const sectionData = $node['Initialize Section 01'].json;
const ragResults = $input.first().json;

console.log('🔍 Processing RAG results for:', sectionData.company_name);

// Extract knowledge context from RAG
let knowledgeContext = '';
if (ragResults && ragResults.documents && ragResults.documents.length > 0) {
  console.log('📚 RAG documents found:', ragResults.documents.length);
  ragResults.documents.forEach((doc, index) => {
    if (doc.pageContent) {
      knowledgeContext += `Knowledge ${index + 1}: ${doc.pageContent}\n\n`;
    }
  });
} else {
  console.log('ℹ️ No RAG documents found, using general business context');
  knowledgeContext = 'General business due diligence principles and methodologies.';
}

// Create enhanced prompt for Section 01
const enhancedPrompt = `You are a Big 4 consulting firm senior analyst creating a professional due diligence report.

Generate a comprehensive "Introduction & Engagement Context" section for: ${sectionData.company_name}

KNOWLEDGE BASE CONTEXT:
${knowledgeContext}

REQUIREMENTS:
1. Write in formal Big 4 consulting style
2. Include engagement scope, methodology, and objectives
3. Reference Big 4 due diligence standards and frameworks
4. Explain the business context and market relevance
5. Minimum 400 words with clear structure
6. Use specific business terminology and professional language
7. Include timeframe and deliverable expectations

Structure the response with these subsections:
- Engagement Overview
- Scope and Methodology  
- Business Context
- Due Diligence Framework
- Expected Outcomes

Generate professional content that sets the foundation for a comprehensive due diligence analysis.`;

console.log('✅ Enhanced prompt created for Section 01');
console.log('📝 Prompt length:', enhancedPrompt.length);

return {
  json: {
    ...sectionData,
    enhanced_prompt: enhancedPrompt,
    knowledge_context: knowledgeContext,
    rag_documents_found: ragResults?.documents?.length || 0
  }
};
